    }
}

contracts/LiquidityZapper.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later

pragma solidity ^0.8.24;

import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Address } from "@openzeppelin/contracts/utils/Address.sol";
import { IPermit2 } from "permit2/src/interfaces/IPermit2.sol";

import { ILiquidityZapper } from "@bush.fi/v3-interfaces/contracts/standalone-utils/ILiquidityZapper.sol";
import { IRouter } from "@bush.fi/v3-interfaces/contracts/vault/IRouter.sol";
import { IVault } from "@bush.fi/v3-interfaces/contracts/vault/IVault.sol";
import { TokenConfig, PoolRoleAccounts } from "@bush.fi/v3-interfaces/contracts/vault/VaultTypes.sol";

import { SingletonAuthentication } from "@bush.fi/v3-vault/contracts/SingletonAuthentication.sol";
import {
    ReentrancyGuardTransient
} from "@bush.fi/v3-solidity-utils/contracts/openzeppelin/ReentrancyGuardTransient.sol";

import { WeightedPoolFactory } from "@bush.fi/v3-pool-weighted/contracts/WeightedPoolFactory.sol";

/**
 * @notice Buys a set of tokens through the Umbra aggregator (umbra.finance) and deposits them as liquidity
 * into a Bush pool, in a single transaction. See {ILiquidityZapper}.
 * @dev Never carries a standing balance across transactions: every token this contract can end up holding
 * (swap outputs, minted BPT) is swept to `recipient` before `zap` returns.
 *
 * Approval design: every swap's `callData` is sent to the single governance-set `_umbraRouter`, a trusted,
 * fixed contract (unlike the pool/factory addresses below, which are caller-chosen). Because it's trusted,
 * ERC20 input funding uses one upfront approval sized to the zap's total input (see `_executeSwaps`) rather
 * than a per-call exact-and-revoke pattern. The only OTHER standing approvals this contract ever holds are to
 * Permit2 and, through it, the immutable `_router` (also fixed at deployment) for post-swap pool
 * tokens ahead of the liquidity join. `pool` and `newPool.factory` are caller-chosen and never granted an
 * approval, so a bad choice there can only misroute the caller's own zap, exactly as if they had called the
 * Router directly.
 */
contract LiquidityZapper is ILiquidityZapper, SingletonAuthentication, ReentrancyGuardTransient {
    using SafeERC20 for IERC20;
    using Address for address;

    IRouter private immutable _router;
    IPermit2 private immutable _permit2;

    address private _umbraRouter;

    constructor(IVault vault, IRouter router, IPermit2 permit2, address umbraRouter) SingletonAuthentication(vault) {
        _router = router;
        _permit2 = permit2;
        _setUmbraRouter(umbraRouter);
    }

    /// @inheritdoc ILiquidityZapper
    function zap(ZapParams calldata p) external payable nonReentrant returns (address pool, uint256 bptAmountOut) {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp > p.deadline) revert ZapExpired();
        if (p.recipient == address(0)) revert ZeroRecipient();
        if (p.swaps.length == 0) revert NoSwaps();

        _executeSwaps(p.tokenIn, p.swaps);

        bool isNewPool = p.pool == address(0);
        IERC20[] memory tokens;
        uint256[] memory amounts;

        if (isNewPool) {
            (pool, tokens, amounts) = _createAndFundNewPool(p.newPool);
            _router.initialize(pool, tokens, amounts, p.minBptAmountOut, false, "");
        } else {
            pool = p.pool;
            (tokens, amounts) = _fundExistingPool(pool);
            _router.addLiquidityUnbalanced(pool, amounts, p.minBptAmountOut, false, "");
        }

        IERC20 bpt = IERC20(pool);
        bptAmountOut = bpt.balanceOf(address(this));
        if (bptAmountOut > 0) {
            bpt.safeTransfer(p.recipient, bptAmountOut);
        }

        // Refund any token dust left over from an unbalanced join (or from a swap that overshot its share).
        for (uint256 i = 0; i < tokens.length; ++i) {
            uint256 dust = tokens[i].balanceOf(address(this));
            if (dust > 0) {
                tokens[i].safeTransfer(p.recipient, dust);
            }
        }

        emit Zapped(msg.sender, p.recipient, pool, isNewPool, bptAmountOut);
    }

    /// @inheritdoc ILiquidityZapper
    function getRouter() external view returns (IRouter) {
        return _router;
    }

    /// @inheritdoc ILiquidityZapper
    function getUmbraRouter() external view returns (address) {
        return _umbraRouter;
    }

    /// @inheritdoc ILiquidityZapper
    function setUmbraRouter(address newUmbraRouter) external authenticate {
        _setUmbraRouter(newUmbraRouter);
    }

    /// @inheritdoc ILiquidityZapper
    function rescue(IERC20 token, address to, uint256 amount) external authenticate nonReentrant {
        if (address(token) == address(0)) {
            Address.sendValue(payable(to), amount);
        } else {
            token.safeTransfer(to, amount);
        }
    }

    function _setUmbraRouter(address newUmbraRouter) private {
        _umbraRouter = newUmbraRouter;
        emit UmbraRouterSet(newUmbraRouter);
    }

    /// Fund and run every swap against the single trusted `_umbraRouter`. For an ERC20 `tokenIn`, the total of
    /// every swap's `amountIn` is pulled from the caller once and approved to the router once upfront (safe as
    /// a standing amount because the router is fixed/trusted, not caller-supplied); for native `tokenIn`, that
    /// same total must match `msg.value`. Each call is checked to have actually moved its declared `tokenOut`.
    function _executeSwaps(IERC20 tokenIn, SwapCall[] calldata swaps) private {
        address umbraRouter = _umbraRouter;
        bool isNative = address(tokenIn) == address(0);

        uint256 totalAmountIn;
        for (uint256 i = 0; i < swaps.length; ++i) {
            totalAmountIn += swaps[i].amountIn;
        }

        if (isNative) {
            if (totalAmountIn != msg.value) revert InputAmountMismatch();
        } else {
            if (msg.value != 0) revert InputAmountMismatch();
            tokenIn.safeTransferFrom(msg.sender, address(this), totalAmountIn);
            tokenIn.forceApprove(umbraRouter, totalAmountIn);
        }

        for (uint256 i = 0; i < swaps.length; ++i) {
            SwapCall calldata sc = swaps[i];

            uint256 outBefore = sc.tokenOut.balanceOf(address(this));
            umbraRouter.functionCallWithValue(sc.callData, sc.value);
            if (sc.tokenOut.balanceOf(address(this)) <= outBefore) revert SwapProducedNoOutput(i);
        }

        if (!isNative) {
            // Revoke any leftover so no stale allowance survives this zap.
            if (tokenIn.allowance(address(this), umbraRouter) != 0) {
                tokenIn.forceApprove(umbraRouter, 0);
            }
        }
    }

    /// Collect this contract's balance of each token the existing pool holds, approving what's needed for the
    /// upcoming Router join along the way.
    function _fundExistingPool(address pool) private returns (IERC20[] memory tokens, uint256[] memory amounts) {
        tokens = getVault().getPoolTokens(pool);
        amounts = new uint256[](tokens.length);

        for (uint256 i = 0; i < tokens.length; ++i) {
            uint256 balance = tokens[i].balanceOf(address(this));
            amounts[i] = balance;
            if (balance > 0) {
                _ensurePermit2Allowance(tokens[i], balance);
            }
        }
    }

    /// Deploy a new weighted pool from the caller-chosen factory, sized to this contract's balance of each
    /// configured token, approving what's needed for the upcoming Router initialize along the way.
    function _createAndFundNewPool(
        NewPoolParams calldata newPool
    ) private returns (address pool, IERC20[] memory tokens, uint256[] memory amounts) {
        (tokens, amounts) = _fundTokens(newPool.tokenConfigs);

        pool = WeightedPoolFactory(newPool.factory).create(
            newPool.name,
            newPool.symbol,
            newPool.tokenConfigs,
            newPool.normalizedWeights,
            newPool.roleAccounts,
            newPool.swapFeePercentage,
            newPool.poolHooksContract,
            newPool.enableDonation,
            newPool.disableUnbalancedLiquidity,
            newPool.salt
        );
    }

    function _fundTokens(
        TokenConfig[] calldata tokenConfigs
    ) private returns (IERC20[] memory tokens, uint256[] memory amounts) {
        uint256 count = tokenConfigs.length;
        tokens = new IERC20[](count);
        amounts = new uint256[](count);

        for (uint256 i = 0; i < count; ++i) {
            IERC20 token = tokenConfigs[i].token;
            tokens[i] = token;

            uint256 balance = token.balanceOf(address(this));
            amounts[i] = balance;
            if (balance > 0) {
                _ensurePermit2Allowance(token, balance);
            }
        }
    }

    /// Two-step Permit2 approval for the immutable, trusted Router (ERC20 -> Permit2, then
    /// Permit2 -> Router), each step lazily skipped once already sufficient. Unlike `_executeSwaps`'s
    /// per-swap approvals, a standing max-approve here is safe because both spenders are fixed at deployment,
    /// never caller-supplied.
    function _ensurePermit2Allowance(IERC20 token, uint256 amount) private {
        if (token.allowance(address(this), address(_permit2)) < amount) {
            token.forceApprove(address(_permit2), type(uint256).max);
        }

        (uint160 currentAllowance, , ) = _permit2.allowance(address(this), address(token), address(_router));
        if (currentAllowance < amount) {
            _permit2.approve(address(token), address(_router), type(uint160).max, type(uint48).max);
        }
    }
}

contracts/MultiRouterLiquidityZapper.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later

pragma solidity ^0.8.24;

import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC4626 } from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import { Address } from "@openzeppelin/contracts/utils/Address.sol";
import { IPermit2 } from "permit2/src/interfaces/IPermit2.sol";

import {
    IMultiRouterLiquidityZapper
} from "@bush.fi/v3-interfaces/contracts/standalone-utils/IMultiRouterLiquidityZapper.sol";
import { IRouter } from "@bush.fi/v3-interfaces/contracts/vault/IRouter.sol";
import { IVault } from "@bush.fi/v3-interfaces/contracts/vault/IVault.sol";
import { TokenConfig } from "@bush.fi/v3-interfaces/contracts/vault/VaultTypes.sol";

import { SingletonAuthentication } from "@bush.fi/v3-vault/contracts/SingletonAuthentication.sol";
import {
    ReentrancyGuardTransient
} from "@bush.fi/v3-solidity-utils/contracts/openzeppelin/ReentrancyGuardTransient.sol";

import { WeightedPoolFactory } from "@bush.fi/v3-pool-weighted/contracts/WeightedPoolFactory.sol";

/**
 * @notice Buys a set of tokens through one or more allowlisted swap routers and deposits them as liquidity into
 * a Bush pool, in a single transaction. See {IMultiRouterLiquidityZapper}.
 * @dev Never carries a standing balance across transactions: every token this contract can end up holding
 * (swap outputs, unspent input, minted BPT, native refunds) is swept to `recipient` before `zap` returns.
 *
 * Approval design: swap routers are caller-chosen per leg (from the allowlist), so each one is approved exactly
 * its leg's `amountIn` right before its call and revoked right after. The only standing approvals this contract
 * ever holds are to Permit2 and, through it, the immutable `_router` (fixed at deployment) for post-swap pool
 * tokens ahead of the liquidity join. `pool` and `newPool.factory` are caller-chosen and never granted an
 * approval, so a bad choice there can only misroute the caller's own zap, exactly as if they had called the
 * Router directly.
 *
 * Never allowlist a token, Permit2, or anything else whose arbitrary calls from this contract could grant
 * approvals: allowlisted routers receive fully caller-controlled calldata.
 */
contract MultiRouterLiquidityZapper is IMultiRouterLiquidityZapper, SingletonAuthentication, ReentrancyGuardTransient {
    using SafeERC20 for IERC20;
    using Address for address;

    // Vault rounds proportional amounts in up (in scaled18, then again converting back to raw), so an amount
    // computed here from raw balances can come out a couple of wei short. Holding back this much of each token
    // when sizing the BPT out keeps the join within the amounts this contract actually holds.
    uint256 private constant _PROPORTIONAL_ROUNDING_MARGIN = 3;

    IRouter private immutable _router;
    IPermit2 private immutable _permit2;

    mapping(address swapRouter => bool allowed) private _isSwapRouterAllowed;

    constructor(
        IVault vault,
        IRouter router,
        IPermit2 permit2,
        address[] memory swapRouters
    ) SingletonAuthentication(vault) {
        _router = router;
        _permit2 = permit2;

        for (uint256 i = 0; i < swapRouters.length; ++i) {
            _setSwapRouterAllowed(swapRouters[i], true);
        }
    }

    /// @dev Swap routers may refund unspent native input, or deliver native output.
    receive() external payable {
        // solhint-disable-previous-line no-empty-blocks
    }

    /// @inheritdoc IMultiRouterLiquidityZapper
    function zap(ZapParams calldata p) external payable nonReentrant returns (address pool, uint256 bptAmountOut) {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp > p.deadline) revert ZapExpired();
        if (p.recipient == address(0)) revert ZeroRecipient();
        if (p.swaps.length == 0) revert NoSwaps();

        _executeSwaps(p.tokenIn, p.swaps);

        bool isNewPool = p.pool == address(0);
        IERC20[] memory tokens = isNewPool ? _tokensOf(p.newPool.tokenConfigs) : getVault().getPoolTokens(p.pool);

        // Boosted pools hold ERC4626 wrappers; swap legs may deliver their underlying instead.
        IERC20[] memory underlyingTokens = _wrapUnderlyingBalances(tokens);

        if (isNewPool) {
            uint256[] memory amounts;
            (pool, amounts) = _createAndFundNewPool(p.newPool, tokens);
            _router.initialize(pool, tokens, amounts, p.minBptAmountOut, false, "");
        } else {
            pool = p.pool;
            _joinExistingPoolProportional(pool, p.minBptAmountOut);
        }

        IERC20 bpt = IERC20(pool);
        bptAmountOut = bpt.balanceOf(address(this));
        if (bptAmountOut > 0) {
            bpt.safeTransfer(p.recipient, bptAmountOut);
        }

        // Refund whatever didn't fit the join: pool-token dust off the pool ratio, plus any input the routers
        // didn't spend.
        for (uint256 i = 0; i < tokens.length; ++i) {
            _sweep(tokens[i], p.recipient);
            if (address(underlyingTokens[i]) != address(0)) {
                _sweep(underlyingTokens[i], p.recipient);
            }
        }
        _sweep(p.tokenIn, p.recipient);

        emit Zapped(msg.sender, p.recipient, pool, isNewPool, bptAmountOut);
    }

    /// @inheritdoc IMultiRouterLiquidityZapper
    function getRouter() external view returns (IRouter) {
        return _router;
    }

    /// @inheritdoc IMultiRouterLiquidityZapper
    function isSwapRouterAllowed(address swapRouter) external view returns (bool) {
        return _isSwapRouterAllowed[swapRouter];
    }

    /// @inheritdoc IMultiRouterLiquidityZapper
    function setSwapRouterAllowed(address swapRouter, bool allowed) external authenticate {
        _setSwapRouterAllowed(swapRouter, allowed);
    }

    /// @inheritdoc IMultiRouterLiquidityZapper
    function rescue(IERC20 token, address to, uint256 amount) external authenticate nonReentrant {
        if (address(token) == address(0)) {
            Address.sendValue(payable(to), amount);
        } else {
            token.safeTransfer(to, amount);
        }
    }

    function _setSwapRouterAllowed(address swapRouter, bool allowed) private {
        _isSwapRouterAllowed[swapRouter] = allowed;
        emit SwapRouterAllowedSet(swapRouter, allowed);
    }

    /// Transfer this contract's entire balance of `token` (native if address(0)) to `to`, if any.
    function _sweep(IERC20 token, address to) private {
        if (address(token) == address(0)) {
            uint256 nativeBalance = address(this).balance;
            if (nativeBalance > 0) {
                Address.sendValue(payable(to), nativeBalance);
            }
        } else {
            uint256 balance = token.balanceOf(address(this));
            if (balance > 0) {
                token.safeTransfer(to, balance);
            }
        }
    }

    /// Fund and run every swap against its own allowlisted router. For an ERC20 `tokenIn`, the total of every
    /// swap's `amountIn` is pulled from the caller once, and each router is approved exactly its leg's
    /// `amountIn` for the duration of its call only; for native `tokenIn`, that same total must match
    /// `msg.value`. Each call is checked to have actually moved its declared `tokenOut`.
    function _executeSwaps(IERC20 tokenIn, SwapCall[] calldata swaps) private {
        bool isNative = address(tokenIn) == address(0);

        uint256 totalAmountIn;
        for (uint256 i = 0; i < swaps.length; ++i) {
            totalAmountIn += swaps[i].amountIn;
        }

        if (isNative) {
            if (totalAmountIn != msg.value) revert InputAmountMismatch();
        } else {
            if (msg.value != 0) revert InputAmountMismatch();
            tokenIn.safeTransferFrom(msg.sender, address(this), totalAmountIn);
        }

        for (uint256 i = 0; i < swaps.length; ++i) {
            SwapCall calldata sc = swaps[i];
            address swapRouter = sc.router;
            if (_isSwapRouterAllowed[swapRouter] == false) revert SwapRouterNotAllowed(i, swapRouter);

            if (!isNative) {
                tokenIn.forceApprove(swapRouter, sc.amountIn);
            }

            uint256 outBefore = sc.tokenOut.balanceOf(address(this));
            swapRouter.functionCallWithValue(sc.callData, sc.value);
            if (sc.tokenOut.balanceOf(address(this)) <= outBefore) revert SwapProducedNoOutput(i);

            // Revoke any leftover so no stale allowance survives this leg.
            if (!isNative && tokenIn.allowance(address(this), swapRouter) != 0) {
                tokenIn.forceApprove(swapRouter, 0);
            }
        }
    }

    /**
     * For each pool token that is an ERC4626 wrapper whose underlying this contract holds, deposit that entire
     * underlying balance into the wrapper, so swap legs can deliver e.g. USDG for a pool that holds steakUSDG.
     * Tokens that aren't wrappers, or whose underlying this contract doesn't hold, are skipped. An underlying that
     * is itself one of the pool's tokens is never wrapped, since the pool wants it as-is.
     *
     * The wrapper is caller-chosen (it comes from the caller's `pool` or `newPool.tokenConfigs`), so it is approved
     * exactly the deposited amount and revoked right after, and can only ever touch the caller's own zap.
     * @return underlyingTokens The underlying wrapped for each pool token (address(0) where none was), to be swept
     * to the recipient afterwards in case the wrapper didn't consume all of it
     */
    function _wrapUnderlyingBalances(IERC20[] memory tokens) private returns (IERC20[] memory underlyingTokens) {
        uint256 count = tokens.length;
        underlyingTokens = new IERC20[](count);
        uint256[] memory amounts = new uint256[](count);

        for (uint256 i = 0; i < count; ++i) {
            IERC20 underlying = _tryGetAsset(tokens[i]);
            if (address(underlying) == address(0) || _contains(tokens, underlying)) continue;

            uint256 amount = underlying.balanceOf(address(this));
            if (amount == 0) continue;

            // Two wrappers of the same underlying: there is no right way to split the balance between them.
            for (uint256 j = 0; j < i; ++j) {
                if (underlyingTokens[j] == underlying) revert AmbiguousUnderlyingToken(underlying);
            }

            underlyingTokens[i] = underlying;
            amounts[i] = amount;
        }

        for (uint256 i = 0; i < count; ++i) {
            IERC20 underlying = underlyingTokens[i];
            if (address(underlying) == address(0)) continue;

            IERC4626 wrapper = IERC4626(address(tokens[i]));
            underlying.forceApprove(address(wrapper), amounts[i]);
            uint256 wrappedAmount = wrapper.deposit(amounts[i], address(this));
            if (underlying.allowance(address(this), address(wrapper)) != 0) {
                underlying.forceApprove(address(wrapper), 0);
            }

            emit UnderlyingWrapped(wrapper, underlying, amounts[i], wrappedAmount);
        }
    }

    /// Returns `token.asset()` if `token` answers it like an ERC4626, or address(0) otherwise (no code, reverts,
    /// or returns something that isn't an address).
    function _tryGetAsset(IERC20 token) private view returns (IERC20) {
        (bool success, bytes memory data) = address(token).staticcall(abi.encodeCall(IERC4626.asset, ()));
        if (success == false || data.length != 32) return IERC20(address(0));

        uint256 asset = abi.decode(data, (uint256));
        if (asset > type(uint160).max) return IERC20(address(0));

        return IERC20(address(uint160(asset)));
    }

    function _contains(IERC20[] memory tokens, IERC20 token) private pure returns (bool) {
        for (uint256 i = 0; i < tokens.length; ++i) {
            if (tokens[i] == token) return true;
        }
        return false;
    }

    /**
     * Join `pool` proportionally with the largest BPT amount this contract's balances of the pool tokens can
     * cover at the pool's current ratio. Any token that is over-represented relative to that ratio is left over
     * and refunded by the caller as dust.
     */
    function _joinExistingPoolProportional(address pool, uint256 minBptAmountOut) private {
        IVault vault = getVault();
        (IERC20[] memory tokens, , uint256[] memory poolBalancesRaw, ) = vault.getPoolTokenInfo(pool);
        uint256 totalSupply = vault.totalSupply(pool);

        uint256[] memory maxAmountsIn = new uint256[](tokens.length);
        uint256 bptAmountOut = type(uint256).max;

        for (uint256 i = 0; i < tokens.length; ++i) {
            uint256 balance = tokens[i].balanceOf(address(this));
            maxAmountsIn[i] = balance;

            uint256 usable = balance > _PROPORTIONAL_ROUNDING_MARGIN ? balance - _PROPORTIONAL_ROUNDING_MARGIN : 0;
            uint256 bptForToken = (usable * totalSupply) / poolBalancesRaw[i];
            if (bptForToken < bptAmountOut) {
                bptAmountOut = bptForToken;
            }

            if (balance > 0) {
                _ensurePermit2Allowance(tokens[i], balance);
            }
        }

        if (bptAmountOut < minBptAmountOut) revert BptAmountOutBelowMin(bptAmountOut, minBptAmountOut);

        _router.addLiquidityProportional(pool, maxAmountsIn, bptAmountOut, false, "");
    }

    /// Deploy a new weighted pool from the caller-chosen factory, sized to this contract's balance of each
    /// configured token, approving what's needed for the upcoming Router initialize along the way.
    function _createAndFundNewPool(
        NewPoolParams calldata newPool,
        IERC20[] memory tokens
    ) private returns (address pool, uint256[] memory amounts) {
        amounts = _fundTokens(tokens);

        pool = WeightedPoolFactory(newPool.factory).create(
            newPool.name,
            newPool.symbol,
            newPool.tokenConfigs,
            newPool.normalizedWeights,
            newPool.roleAccounts,
            newPool.swapFeePercentage,
            newPool.poolHooksContract,
            newPool.enableDonation,
            newPool.disableUnbalancedLiquidity,
            newPool.salt
        );
    }

    function _tokensOf(TokenConfig[] calldata tokenConfigs) private pure returns (IERC20[] memory tokens) {
        tokens = new IERC20[](tokenConfigs.length);
        for (uint256 i = 0; i < tokenConfigs.length; ++i) {
            tokens[i] = tokenConfigs[i].token;
        }
    }

    function _fundTokens(IERC20[] memory tokens) private returns (uint256[] memory amounts) {
        uint256 count = tokens.length;
        amounts = new uint256[](count);

        for (uint256 i = 0; i < count; ++i) {
            IERC20 token = tokens[i];

            uint256 balance = token.balanceOf(address(this));
            amounts[i] = balance;
            if (balance > 0) {
                _ensurePermit2Allowance(token, balance);
            }
        }
    }

    /// Two-step Permit2 approval for the immutable, trusted Router (ERC20 -> Permit2, then
    /// Permit2 -> Router), each step lazily skipped once already sufficient. Unlike `_executeSwaps`'s
    /// per-swap approvals, a standing max-approve here is safe because both spenders are fixed at deployment,
    /// never caller-supplied.
    function _ensurePermit2Allowance(IERC20 token, uint256 amount) private {
        if (token.allowance(address(this), address(_permit2)) < amount) {
            token.forceApprove(address(_permit2), type(uint256).max);
        }

        (uint160 currentAllowance, , ) = _permit2.allowance(address(this), address(token), address(_router));
        if (currentAllowance < amount) {
            _permit2.approve(address(token), address(_router), type(uint160).max, type(uint48).max);
        }
    }
}

